result.text:
    const sub = PLANO.subcuentas.find((s) => s.code === key);
    const madre = pgcNombre(key);
    const nombre = (propia && propia.name) || (sub && sub.name) || madre;
    row = {
      code: key,
      name: nombre || `Cuenta ${key}`,
      balance: balancePorDefecto(key),
      pl: plPorDefecto(key),
    };
  }
  CACHE_CUENTAS.set(key, row);
  return row;
}

